use crate::model::ModelError;

/// A sound a brew can play at a step boundary or at the finish: one of the
/// sounds the app ships (`assets/sounds/<id>.mp3`, generated by
/// `scripts/gen-sounds.py`). A closed set; each knows its id, name and
/// length, so the picker can show whether it outlasts a short step.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Sound {
    TempleBlock,
    WoodenClappers,
    Tingsha,
    WaterDrop,
    Kalimba,
    BreathAndBowl,
    BambooTock,
    SingingBowl,
}

impl Sound {
    /// Every sound, in the picker's order.
    pub const ALL: [Self; 8] = [
        Self::TempleBlock,
        Self::WoodenClappers,
        Self::Tingsha,
        Self::WaterDrop,
        Self::Kalimba,
        Self::BreathAndBowl,
        Self::BambooTock,
        Self::SingingBowl,
    ];

    /// The step boundary's sound before one is chosen: the one every step
    /// played before the choice existed, so an update changes nothing.
    pub const DEFAULT_STEP: Self = Self::BreathAndBowl;

    /// The finish's sound before one is chosen: the long bowl, so the end
    /// does not sound like one more step.
    pub const DEFAULT_FINISH: Self = Self::SingingBowl;

    /// The id: the asset's file stem and the string persisted in storage.
    pub fn id(self) -> &'static str {
        match self {
            Self::TempleBlock => "temple-block",
            Self::WoodenClappers => "wooden-clappers",
            Self::Tingsha => "tingsha",
            Self::WaterDrop => "water-drop",
            Self::Kalimba => "kalimba",
            Self::BreathAndBowl => "breath-and-bowl",
            Self::BambooTock => "bamboo-tock",
            Self::SingingBowl => "singing-bowl",
        }
    }

    /// The picker's name: `Temple block`.
    pub fn label(self) -> &'static str {
        match self {
            Self::TempleBlock => "Temple block",
            Self::WoodenClappers => "Wooden clappers",
            Self::Tingsha => "Tingsha",
            Self::WaterDrop => "Water drop",
            Self::Kalimba => "Kalimba",
            Self::BreathAndBowl => "Breath and bowl",
            Self::BambooTock => "Bamboo tock",
            Self::SingingBowl => "Singing bowl",
        }
    }

    /// How long the asset plays, in ms.
    pub fn duration_ms(self) -> u32 {
        match self {
            Self::SingingBowl => 2000,
            _ => 1000,
        }
    }

    /// The length in seconds to one decimal: `1.0 s`.
    pub fn length_label(self) -> String {
        let tenths = self.duration_ms().div_ceil(100);
        format!("{}.{} s", tenths / 10, tenths % 10)
    }

    /// Parses an [`Sound::id`] strictly: anything else is
    /// [`ModelError::UnknownSound`]. For user input; storage reads go
    /// through [`crate::model::Settings::from_storage`].
    pub fn try_parse(raw: &str) -> Result<Self, ModelError> {
        Self::ALL
            .into_iter()
            .find(|sound| sound.id() == raw)
            .ok_or_else(|| ModelError::UnknownSound(raw.to_owned()))
    }
}
